public sealed class OrdersApiOptions
{
    public const string SectionName = "OrdersApi";
    public string BaseUrl { get; set; } = "";
    public int TimeoutSeconds { get; set; } = 30;
}

// Program.cs
builder.Services.Configure<OrdersApiOptions>(
    builder.Configuration.GetSection(OrdersApiOptions.SectionName));

public sealed class OrdersApiClient
{
    private readonly HttpClient _http;
    private readonly OrdersApiOptions _options;

    public OrdersApiClient(HttpClient http, IOptions<OrdersApiOptions> options)
    {
        _http = http;
        _options = options.Value; // snapshot at first resolve — won't reload
        _http.BaseAddress = new Uri(_options.BaseUrl);
        _http.Timeout = TimeSpan.FromSeconds(_options.TimeoutSeconds);
    }
}

[ApiController]
[Route("api/orders")]
public class OrdersController : ControllerBase
{
    private readonly IOptionsSnapshot<OrdersApiOptions> _options;

    public OrdersController(IOptionsSnapshot<OrdersApiOptions> options)
        => _options = options;

    [HttpGet("config")]
    public IActionResult GetConfig()
        => Ok(new { _options.Value.BaseUrl, _options.Value.TimeoutSeconds });
    // Value recomputed when this request's scope starts
}

public sealed class FeatureFlags
{
    public bool EnableNewCheckout { get; set; }
    public bool EnableBetaSearch { get; set; }
}

public sealed class FeatureFlagService
{
    private volatile FeatureFlags _flags;

    public FeatureFlagService(IOptionsMonitor<FeatureFlags> monitor)
    {
        _flags = monitor.CurrentValue;
        monitor.OnChange(updated => _flags = updated);
    }

    public bool IsEnabled(string feature) => feature switch
    {
        "NewCheckout" => _flags.EnableNewCheckout,
        "BetaSearch" => _flags.EnableBetaSearch,
        _ => false
    };
}

